// exactData is bench/exact.py's data: y = (i² mod 97)/7 − 3 and
// x = i + (i mod 3)/8, every value correctly rounded on both sides.
func exactData(n int) (y, x []float64) {
	y = make([]float64, n)
	x = make([]float64, n)
	for i := range n {
		fi := float64(i)
		y[i] = math.Mod(fi*fi, 97)/7.0 - 3.0
		x[i] = fi + math.Mod(fi, 3)/8.0
	}
	return y, x
}

func TestSampleRulesMatchSciPyExactly(t *testing.T) {
	for _, c := range sciPyExact {
		y, x := exactData(c.n)
		var got float64
		var err error
		switch c.name {
		case "trapezoid_x":
			got, err = Trapezoid(y, x, 0)
		case "trapezoid_dx":
			got, err = Trapezoid(y, nil, 0.375)
		case "simpson_x":
			got, err = Simpson(y, x, 0)
		case "simpson_dx":
			got, err = Simpson(y, nil, 0.375)
		case "cumtrapz_last", "cumtrapz_mid":
			var cs []float64
			cs, err = CumulativeTrapezoid(y, x, 0, true)
			if c.name == "cumtrapz_last" {
				got = cs[len(cs)-1]
			} else {
				got = cs[len(cs)/2]
			}
		case "romb":
			got, err = Romb(y, 0.375)
		}
		if err != nil {
			t.Fatalf("%s n=%d: %v", c.name, c.n, err)
		}
		if math.Float64bits(got) != math.Float64bits(c.want) {
			t.Errorf("%s n=%d: %v, SciPy %v", c.name, c.n, got, c.want)
		}
	}
}

