func TestAxisRulesMatchSciPyExactly(t *testing.T) {
	for _, c := range sciPyExactND {
		n := c.shape[0] * c.shape[1] * c.shape[2]
		data := make([]float64, n)
		for i := range data {
			fi := float64(i)
			data[i] = math.Mod(fi*fi, 97)/7.0 - 3.0
		}
		a, _ := ndarray.FromData(data, c.shape...)
		m := c.shape[c.axis]
		x := make([]float64, m)
		for j := range x {
			fj := float64(j)
			x[j] = fj + math.Mod(fj, 3)/8.0
		}
		var got *ndarray.Array
		var err error
		switch c.name {
		case "trapezoid_x":
			got, err = TrapezoidND(a, x, 0, c.axis)
		case "trapezoid_dx":
			got, err = TrapezoidND(a, nil, 0.375, c.axis)
		case "simpson_x":
			got, err = SimpsonND(a, x, 0, c.axis)
		case "simpson_dx":
			got, err = SimpsonND(a, nil, 0.375, c.axis)
		case "cumtrapz_x":
			got, err = CumulativeTrapezoidND(a, x, 0, c.axis, true)
		case "cumtrapz_dx":
			got, err = CumulativeTrapezoidND(a, nil, 0.375, c.axis, false)
		}
		if err != nil {
			t.Fatalf("%v axis %d %s: %v", c.shape, c.axis, c.name, err)
		}
		g, _ := ndarray.Data[float64](got)
		if len(g) != len(c.want) {
			t.Fatalf("%v axis %d %s: %d values, SciPy %d", c.shape, c.axis, c.name, len(g), len(c.want))
		}
		for i := range g {
			if math.Float64bits(g[i]) != math.Float64bits(c.want[i]) {
				t.Errorf("%v axis %d %s [%d]: %v, SciPy %v", c.shape, c.axis, c.name, i, g[i], c.want[i])
				break
			}
		}
	}
}

func TestAxisRulesEdges(t *testing.T) {
	data := make([]float64, 15)
	for i := range data {
		data[i] = float64(i * i % 7)
	}
	a, _ := ndarray.FromData(data, 3, 5)
	ia := a.AsType(ndarray.Int64)
	bad := []float64{0, 1} // the wrong number of abscissae for either axis
	for axis := range 2 {
		// Integer samples are converted, as NumPy converts them.
		for name, f := range map[string]func(*ndarray.Array) (*ndarray.Array, error){
			"trapezoid":  func(y *ndarray.Array) (*ndarray.Array, error) { return TrapezoidND(y, nil, 0.5, axis) },
			"simpson":    func(y *ndarray.Array) (*ndarray.Array, error) { return SimpsonND(y, nil, 0.5, axis) },
			"cumulative": func(y *ndarray.Array) (*ndarray.Array, error) { return CumulativeTrapezoidND(y, nil, 0.5, axis, true) },
		} {
			want, err1 := f(a)
			got, err2 := f(ia)
			if err1 != nil || err2 != nil {
				t.Fatal(name, err1, err2)
			}
			w, _ := ndarray.Data[float64](want)
			g, _ := ndarray.Data[float64](got)
			for i := range w {
				if w[i] != g[i] {
					t.Errorf("%s axis %d: int64 %v, float64 %v", name, axis, g, w)
					break
				}
			}
		}
		if _, err := TrapezoidND(a, bad, 0, axis); err == nil {
			t.Errorf("trapezoid axis %d: no error for the wrong x", axis)
		}
		if _, err := SimpsonND(a, bad, 0, axis); err == nil {
			t.Errorf("simpson axis %d: no error for the wrong x", axis)
		}
		if _, err := CumulativeTrapezoidND(a, bad, 0, axis, false); err == nil {
			t.Errorf("cumulative axis %d: no error for the wrong x", axis)
		}
	}
	// No lanes at all: an empty result, and no complaint about x.
	empty, _ := ndarray.FromData([]float64{}, 2, 3, 0)
	for _, f := range []func() (*ndarray.Array, error){
		func() (*ndarray.Array, error) { return TrapezoidND(empty, bad, 0, 1) },
		func() (*ndarray.Array, error) { return SimpsonND(empty, bad, 0, 1) },
		func() (*ndarray.Array, error) { return CumulativeTrapezoidND(empty, bad, 0, 1, true) },
	} {
		if r, err := f(); err != nil || r.Size() != 0 {
			t.Errorf("empty: %v %v", r, err)
		}
	}
	if _, err := SimpsonND(a, nil, 1, 2); err == nil {
		t.Error("simpson: no error for an axis out of range")
	}
	// Contiguous lanes, empty or of one sample.
	none, _ := ndarray.FromData([]float64{}, 0, 5)
	if r, err := TrapezoidND(none, bad, 0, 1); err != nil || r.Size() != 0 {
		t.Errorf("no lanes: %v %v", r, err)
	}
	if r, err := SimpsonND(none, bad, 0, 1); err != nil || r.Size() != 0 {
		t.Errorf("no lanes: %v %v", r, err)
	}
	single, _ := ndarray.FromData([]float64{1, 2, 3}, 3, 1)
	if r, err := TrapezoidND(single, nil, 1, 1); err != nil || r.At(2) != 0 {
		t.Errorf("one-sample lanes: %v %v", r, err)
	}
	// Long lanes give the 1-D rules' values.
	y, x := exactData(600)
	long, _ := ndarray.FromData(y, 2, 300)
	for k := range 2 {
		lane, xl := y[300*k:300*k+300], x[:300]
		w1, _ := Trapezoid(lane, xl, 0)
		w2, _ := Simpson(lane, xl, 0)
		g1, _ := TrapezoidND(long, xl, 0, 1)
		g2, _ := SimpsonND(long, xl, 0, 1)
		if g1.At(k) != w1 || g2.At(k) != w2 {
			t.Errorf("lane %d: %v %v, 1-D %v %v", k, g1.At(k), g2.At(k), w1, w2)
		}
	}
	// Fewer than two samples integrate to 0.
	if v, err := Trapezoid([]float64{3}, nil, 1); err != nil || v != 0 {
		t.Errorf("one sample: %v %v", v, err)
	}
}
